var g singleflight.Group
func Home(ctx context.Context) ([]byte, error) {
    if v, ok := cache.Get("home"); ok { return v, nil }
    v, err, _ := g.Do("home", func() (any, error) {
        b, err := renderHome(ctx); if err == nil { cache.Set("home", b, 5*time.Minute) }
        return b, err
    })
    if err != nil { return nil, err }
    return v.([]byte), nil
}
